script:
// Nova: a cheerful flight copilot who comments on what you're doing. All lines are original.
const LINES = {
  start: ['Nova here. Checklists done, snacks stowed. Ready when you are!', 'Systems green. I double-checked the bolts. Twice.', "Good morning, pilot. Let's make some orbital mechanics happen."],
  liftoff: ['And we are off the ground! Keep that nose steady.', 'Liftoff! Hear that rumble? That is the sound of physics losing.', 'Clear of the pad. Start leaning east when you feel like it.'],
  stage: ['Staging! Goodbye, faithful hardware.', 'Separation confirmed. That part has a long walk home.', 'New stage, new us.'],
  maxq: ['This is the bumpy part. Ease the throttle if she shakes.', 'Max pressure. Hold steady, it gets smoother up high.'],
  space: ['We are above the air! The view up here is unreal.', 'Space! The sky just went black. Wow.'],
  orbit: ['Periapsis is above the atmosphere. We are officially in orbit!', 'Orbit achieved. We are falling around the planet now. Elegantly.'],
  hot: ['It is getting toasty out there. Nose up, show them the heat tiles!', 'Hull temperature climbing. I would love to not melt today.'],
  low: ['Ground is coming up. Slow and gentle, please.', 'Watch the descent rate, we want a landing, not a crater.'],
  landed: ['Touchdown! Smooth as a pebble on a pond.', 'We are down. I will put the kettle on.'],
  crash: ['…Okay. That one we will call a learning experience.', 'Note to self: the ground is harder than it looks.'],
  idle: ['Fun fact: going faster sideways is how you stop falling down.', 'Tip: burn prograde at apoapsis to raise the other side of the orbit.', 'If the steering feels twitchy, try Fine mode. Caps Lock on a keyboard.', 'Remember: the autopilot can fly the ascent if you just want to sightsee.'],
};
const pick = k => LINES[k][Math.floor(Math.random() * LINES[k].length)];
let bub = null, hideAt = 0, t = 0, last = {}, flags = {}, idleAt = 60, on = api.storage.get('on') !== false;
function say(k) {
  if (!on) return;
  if (last[k] && t - last[k] < 25) return; last[k] = t;
  if (!bub || !bub.isConnected) {
    bub = api.ui.panel('nova');
    bub.style.cssText = 'left:50%;transform:translateX(-50%);bottom:calc(190px + var(--sab));max-width:min(340px,70vw);padding:7px 11px 7px 38px;border-radius:14px;background:rgba(36,16,58,0.88);border:1px solid #d9a6ff;color:#f3e6ff;font:12.5px/1.35 system-ui,sans-serif;transition:opacity .4s;opacity:0;position:absolute';
  }
  bub.innerHTML = '<span style="position:absolute;left:9px;top:50%;transform:translateY(-50%);font-size:20px">🧑‍🚀</span><b style="color:#d9a6ff">Nova:</b> ' + pick(k);
  bub.style.opacity = '1'; hideAt = t + 5.5;
}
api.onFlightStart(f => { t = 0; last = {}; flags = { landedStart: f && (f.landed || f.contact) }; idleAt = 70; setTimeout(() => say('start'), 1200); });
api.onStage(() => say('stage'));
api.onCrash(() => say('crash'));
api.onUpdate((dt, f) => {
  if (!f) return; t += dt;
  if (bub && hideAt && t > hideAt) { bub.style.opacity = '0'; hideAt = 0; }
  if (!flags.liftoff && flags.landedStart && f.radar > 30 && f.vSpeed > 3) { flags.liftoff = 1; say('liftoff'); }
  if (!flags.maxq && f.q > 25) { flags.maxq = 1; say('maxq'); }
  if (!flags.space && f.body === 'Kampa' && f.alt > 70000) { flags.space = 1; say('space'); }
  if (!flags.orbit && f.situation === 'orbiting' && f.pe > 70000) { flags.orbit = 1; say('orbit'); }
  if (f.heat > 0.75) say('hot');
  if (f.radar < 400 && f.vSpeed < -25 && !f.landed) say('low');
  if (flags.liftoff && f.landed && f.srfSpeed < 1 && !flags.landed) { flags.landed = 1; say('landed'); }
  if (t > idleAt) { idleAt = t + 90 + Math.random() * 60; say('idle'); }
});
api.addUIButton({ label: 'Nova', icon: '🧑‍🚀', where: 'flight', onClick: () => { on = !on; api.storage.set('on', on); if (on) { last = {}; say('start'); } else if (bub) bub.style.opacity = '0'; api.toast('Nova copilot ' + (on ? 'on' : 'muted'), 1200); } });
